// Runs before Claude edits or writes a file (PreToolUse hook).
//
// Enforces the "never edit" rules from AGENTS.md so they cannot be broken by
// accident:
//   - dist/ is generated by `npm run build`; edits there are lost and must not
//     be committed. Edit apps/<tool>/ or packages/ui/ instead.
//   - The local course-file folders may hold real student/course material.
//     Claude must not write into them.
//   - tests/import-baseline.json may change only after a reviewed, intentional
//     business-logic change, so Claude must ask the person first.
//
// Claude Code passes the tool call as JSON on standard input. This script
// prints a decision as JSON. Printing nothing lets the edit go ahead.

import path from 'node:path';

const DENY = [
  {
    prefix: 'dist/',
    reason: 'dist/ is generated by `npm run build` and must never be edited or committed. Edit the source in apps/<tool>/ or packages/ui/ and rebuild.',
  },
  {
    prefix: 'tests/test files/',
    reason: 'tests/test files/ holds private course files for local regression only. Claude must not write there; the person manages these files themselves.',
  },
  {
    prefix: 'tests/test-files/',
    reason: 'tests/test-files/ holds private course files for local regression only. Claude must not write there; the person manages these files themselves.',
  },
  {
    prefix: 'tests/local-baselines/',
    reason: 'tests/local-baselines/ holds private, reviewed regression counts. Recapture them only with `npm run test:e2e:local -- --capture` after a person has reviewed the change.',
  },
];

const ASK = [
  {
    prefix: 'tests/import-baseline.json',
    reason: 'tests/import-baseline.json is the processing-code parity gate. AGENTS.md allows updating it only after a reviewed, intentional business-logic change, never to make a failing test pass or for UI-only changes. Approve only if that applies.',
  },
];

function decide(decision, reason) {
  process.stdout.write(JSON.stringify({
    hookSpecificOutput: {
      hookEventName: 'PreToolUse',
      permissionDecision: decision,
      permissionDecisionReason: reason,
    },
  }));
}

let input = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', (chunk) => { input += chunk; });
process.stdin.on('end', () => {
  let call;
  try { call = JSON.parse(input); } catch { return; } // Unreadable input: don't block.

  const target = call?.tool_input?.file_path ?? call?.tool_input?.notebook_path;
  if (!target) return;

  const projectDir = process.env.CLAUDE_PROJECT_DIR || call.cwd || process.cwd();
  const relative = path.relative(projectDir, path.resolve(projectDir, target)).split(path.sep).join('/');
  if (relative.startsWith('../')) return; // Outside the project: not our concern.

  const matches = (rule) => relative === rule.prefix || relative.startsWith(rule.prefix);
  const denied = DENY.find(matches);
  if (denied) return decide('deny', denied.reason);
  const asked = ASK.find(matches);
  if (asked) return decide('ask', asked.reason);
});
